using System;\nusing NUnit.Framework;\nusing RestSharp;\nusing TechTalk.SpecFlow;\nusing AutomationFramework.API.BusinessLogic;\nusing AutomationFramework.Core.Utilities;\nusing Serilog;\nusing Newtonsoft.Json;\n\nnamespace AutomationFramework.API.StepDefinitions\n{\n    [Binding]\n    public class PetstoreSteps\n    {\n        private readonly ScenarioContext _scenarioContext;\n        private readonly PetApiHelper _petApiHelper;\n        private RestResponse _response;\n\n        public PetstoreSteps(ScenarioContext scenarioContext)\n        {\n            _scenarioContext = scenarioContext;\n            _petApiHelper = new PetApiHelper();\n        }\n\n        [Given(\"the API endpoint is \\\"(.*)\\\"\")]\n        public void GivenTheApiEndpointIs(string endpoint)\n        {\n            _scenarioContext[\"Endpoint\"] = endpoint;\n            Log.Information(\"Endpoint set to: {Endpoint}\", endpoint);\n        }\n\n        [When(\"I send a POST request with payload\")]\n        public void WhenISendAPostRequestWithPayload()\n        {\n            var endpoint = _scenarioContext[\"Endpoint\"].ToString();\n            var payload = new { id = 123, name = \"doggie\", status = \"available\" };\n            _response = _petApiHelper.SendPostRequest(endpoint, payload);\n            Log.Information(\"POST request sent to {Endpoint} with payload: {Payload}\", endpoint, JsonConvert.SerializeObject(payload));\n        }\n\n        [When(\"I send a GET request with petId\")]\n        public void WhenISendAGetRequestWithPetId()\n        {\n            var endpoint = _scenarioContext[\"Endpoint\"].ToString();\n            var petId = 123;\n            _response = _petApiHelper.SendGetRequest(endpoint.Replace(\"{petId}\", petId.ToString()));\n            Log.Information(\"GET request sent to {Endpoint}\", endpoint);\n        }\n\n        [When(\"I send a PUT request with updated payload\")]\n        public void WhenISendAPutRequestWithUpdatedPayload()\n        {\n            var endpoint = _scenarioContext[\"Endpoint\"].ToString();\n            var payload = new { id = 123, name = \"doggie\", status = \"sold\" };\n            _response = _petApiHelper.SendPutRequest(endpoint, payload);\n            Log.Information(\"PUT request sent to {Endpoint} with payload: {Payload}\", endpoint, JsonConvert.SerializeObject(payload));\n        }\n\n        [When(\"I send a DELETE request with petId\")]\n        public void WhenISendADeleteRequestWithPetId()\n        {\n            var endpoint = _scenarioContext[\"Endpoint\"].ToString();\n            var petId = 123;\n            _response = _petApiHelper.SendDeleteRequest(endpoint.Replace(\"{petId}\", petId.ToString()));\n            Log.Information(\"DELETE request sent to {Endpoint}\", endpoint);\n        }\n\n        [Then(\"the response status code should be 200\")]\n        public void ThenTheResponseStatusCodeShouldBe